import { HttpContext, HttpContextToken, HttpInterceptorFn } from '@angular/common/http';
import { inject } from '@angular/core';
import { Session } from './session';

/** The header that tells the server the date this screen shows the sheet as of. */
export const AS_OF_HEADER = 'X-As-Of';

/** Marks a read that is always answered with the sheet as it is now, whatever the screen's as-of date. */
export const LIVE_READ = new HttpContextToken<boolean>(() => false);

// Sends the screen's as-of date, while one is set, with every request to the server: reads answer
// with the sheet as it stood then, and every change is refused.
export const asOfInterceptor: HttpInterceptorFn = (req, next) => {
  const asOf = inject(Session).asOf();
  return next(asOf && !req.context.get(LIVE_READ) ? req.clone({ setHeaders: { [AS_OF_HEADER]: asOf } }) : req);
};

/** The options of a read answered with the sheet as it stood at the end of a date, whatever the screen's
 *  as-of date; none for a read as the screen shows it. */
export function readAsOf(date?: string): { headers?: Record<string, string>; context?: HttpContext } {
  return date === undefined ? {} : { headers: { [AS_OF_HEADER]: date }, context: new HttpContext().set(LIVE_READ, true) };
}
import { Component, inject, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { Session } from '../../core/session';

// The date this screen shows the sheet as of, set and cleared here. While it is set, everything on
// the screen is as it stood at the end of that date, and every change is refused; other users'
// screens are unaffected.
@Component({
  selector: 'app-sheet-as-of',
  imports: [ReactiveFormsModule],
  template: `
    @if (session.sheet()) {
      <form [formGroup]="form" (ngSubmit)="set()" aria-label="Show the sheet as of a date">
        <span>As of: <strong data-testid="sheet-asof">{{ session.asOf() ?? '' }}</strong></span>
        <label for="asof-date">Show as of</label>
        <input id="asof-date" type="date" data-testid="asof-date" formControlName="date" />
        <button type="submit" data-testid="asof-set" [disabled]="busy()">Set as-of</button>
        <button type="button" data-testid="asof-clear" [disabled]="busy()" (click)="clear()">Clear as-of</button>
        @if (error()) {
          <p role="alert" data-testid="asof-error">{{ error() }}</p>
        }
      </form>
    }
  `,
})
export class SheetAsOf {
  protected readonly session = inject(Session);

  protected readonly date = new FormControl('', { nonNullable: true });
  protected readonly form = new FormGroup({ date: this.date });
  protected readonly busy = signal(false);
  protected readonly error = signal('');

  constructor() {
    this.date.valueChanges.subscribe(() => this.error.set(''));
  }

  protected async set(): Promise<void> {
    const date = this.date.value.trim();
    this.error.set('');
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
      this.error.set('Type a date as yyyy-mm-dd.');
      return;
    }
    await this.show(date);
  }

  protected async clear(): Promise<void> {
    this.error.set('');
    await this.show(null);
  }

  private async show(date: string | null): Promise<void> {
    if (this.busy()) return;
    this.busy.set(true);
    try {
      await this.session.setAsOf(date);
    } catch {
      this.error.set('The sheet could not be shown as of that date.');
    } finally {
      this.busy.set(false);
    }
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';

export interface SheetView {
  id: string;
  /** The sheet's today (yyyy-mm-dd): every date decision and default date uses it, never the real clock. */
  today: string;
  /** An archived sheet stays visible, and every change on it is refused. */
  archived: boolean;
  /** The number of the sheet's last bulk settle batch; null when it has had none. */
  lastSettleBatch: number | null;
  /** The role the signed-in user acts in on the sheet: clerk, steward, viewer or restricted. */
  role: string;
}

// Who is signed in (a typed name, no password) and which sheet is active. Everything else in the
// app is kept per sheet and reads the active sheet id from here.
